#include "caret_delete_witness.hpp"

#include <cstdio>
#include <fstream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

// SPEC-M3-ordered-commands 15.1, ruling 2 2.1 "how the meaning of a completion
// is tested": the decider as a pure function of the recorded inputs, against
// labels it did not produce.
//
// The fixture is tests/caret_delete_witness_fixture.tsv, generated by
// tools/make_caret_delete_fixture.py from the committed native G run (every
// uni1 cell, N = 5, VERDICT G-HOLDS).  Its labels come from the saved
// documents: a cell that lost as many characters as it has ops is `deleted`
// throughout, one that lost none is `noop`.
//
// What must hold:
//   W     the decider labels every op as the saved document says (form 1 over
//         the fixture);
//   G     before every recorded key the decider would post it (judgeBeforeKey
//         returns nullptr on every recorded before-read).
// Red cases, each a variant that must FAIL on the same inputs:
//   R1    undo-only (spec 5.4 as pinned) mislabels exactly 6 ops in every g1
//         and g2 cell -- grouping reached -- and none elsewhere;
//   R2    no guard: a recorded t1 op whose after-read is replaced by a
//         different paragraph's (the caret moved, the document did not) is
//         KeyUndo without the guard and BoundaryNoop with it;
//   R3    no a11y guard: with the paragraph reads absent, a decider that went
//         on is the undo-only one (R1's 6 per cell); the real one refuses
//         before the key on every op;
//   R4    a failed after-read on the paragraph branch is never BoundaryNoop.

namespace {
namespace cd = probe::caretdelete;

struct Op {
  std::string arm;
  int round = 0;
  int index = 0;
  cd::Key key = cd::Key::Backspace;
  bool deleted = false;
  std::string undoBefore, undoAfter;
  int beforePos = -1, afterPos = -1;
  std::string beforeContent, afterContent;
};

int gFailures = 0;

void check(bool condition, const std::string &what) {
  if (!condition) {
    ++gFailures;
    std::printf("FAIL %s\n", what.c_str());
  }
}

std::string unhex(const std::string &field) {
  if (field == "=")
    return {};
  std::string out;
  for (std::size_t i = 0; i + 1 < field.size(); i += 2)
    out += static_cast<char>(std::stoi(field.substr(i, 2), nullptr, 16));
  return out;
}

std::vector<Op> load(const char *path) {
  std::ifstream in(path);
  std::vector<Op> ops;
  std::string line;
  while (std::getline(in, line)) {
    if (line.empty() || line[0] == '#')
      continue;
    std::vector<std::string> f;
    std::stringstream s(line);
    std::string cell;
    while (std::getline(s, cell, '\t'))
      f.push_back(cell);
    if (f.size() != 11) {
      check(false, "fixture line with " + std::to_string(f.size()) + " fields");
      continue;
    }
    Op op;
    op.arm = f[0];
    op.round = std::stoi(f[1]);
    op.index = std::stoi(f[2]);
    op.key = f[3] == "delete" ? cd::Key::Delete : cd::Key::Backspace;
    op.deleted = f[4] == "deleted";
    op.undoBefore = unhex(f[5]);
    op.undoAfter = unhex(f[6]);
    op.beforePos = std::stoi(f[7]);
    op.beforeContent = unhex(f[8]);
    op.afterPos = std::stoi(f[9]);
    op.afterContent = unhex(f[10]);
    ops.push_back(op);
  }
  return ops;
}

cd::ParagraphRead beforeRead(const Op &op) {
  return cd::paragraphReadOf(op.beforeContent, op.beforePos, 0);
}
cd::ParagraphRead afterRead(const Op &op) {
  return cd::paragraphReadOf(op.afterContent, op.afterPos, 0);
}

bool saysDeleted(const cd::Judgement &j) { return j.verdict == cd::Verdict::KeyUndo; }

// Spec 5.4 as pinned: the payload changed and parses to >= 1 action, else no
// effect.  Transcribed here so that the test can show it fails.
cd::Judgement undoOnly(const Op &op) {
  cd::Judgement j;
  const probe::merge::UndoSummary after =
      probe::merge::summarizeUndoPayload(op.undoAfter);
  j.verdict = op.undoAfter != op.undoBefore && after.ok && after.actions >= 1
                  ? cd::Verdict::KeyUndo
                  : cd::Verdict::BoundaryNoop;
  return j;
}

// The paired decider with the guard removed.
cd::Judgement unguarded(const Op &op, const cd::ParagraphRead &after) {
  cd::Judgement j = undoOnly(op);
  if (j.verdict == cd::Verdict::KeyUndo)
    return j;
  if (after.ok && cd::contentDiffers(beforeRead(op), after))
    j.verdict = cd::Verdict::KeyUndo;
  return j;
}

std::string cellOf(const Op &op) { return op.arm + " r" + std::to_string(op.round); }
} // namespace

int main(int argc, char **argv) {
  if (argc != 2) {
    std::printf("usage: %s FIXTURE.tsv\n", argv[0]);
    return 2;
  }
  const std::vector<Op> ops = load(argv[1]);
  // Non-vacuity: the fixture must be the run it says it is, not an empty file
  // that every rule below would pass.
  check(ops.size() == 405, "fixture has " + std::to_string(ops.size()) +
                               " ops, the G run's uni1 cells have 405");

  std::map<std::string, int> undoOnlyWrong, pairedWrong, cellOps;
  int paragraphBranch = 0;
  for (const Op &op : ops) {
    const std::string at = cellOf(op) + " op " + std::to_string(op.index);
    ++cellOps[cellOf(op)];
    // G
    check(cd::judgeBeforeKey(true, true, beforeRead(op)) == nullptr,
          at + ": the decider would not have posted a recorded key");
    // W
    const cd::Judgement j = cd::judgeAtReturn(op.key, op.undoBefore, true,
                                              op.undoAfter, beforeRead(op),
                                              afterRead(op));
    check(j.verdict != cd::Verdict::Refused, at + ": refused (" +
                                                 std::string(j.stage ? j.stage : "") + ")");
    if (saysDeleted(j) != op.deleted)
      ++pairedWrong[cellOf(op)];
    if (j.byParagraph) {
      ++paragraphBranch;
      check(j.after.actions >= 1, at + ": paragraph branch with actionsAfter 0");
    }
    // R1
    if (saysDeleted(undoOnly(op)) != op.deleted)
      ++undoOnlyWrong[cellOf(op)];
  }
  for (const auto &[cell, n] : cellOps) {
    check(pairedWrong[cell] == 0,
          "W " + cell + ": paired mislabels " + std::to_string(pairedWrong[cell]));
    const bool grouped = cell.rfind("g1 ", 0) == 0 || cell.rfind("g2 ", 0) == 0;
    check(undoOnlyWrong[cell] == (grouped ? 6 : 0),
          "R1 " + cell + ": undo-only mislabels " +
              std::to_string(undoOnlyWrong[cell]) + ", expected " +
              (grouped ? "6" : "0"));
  }
  // The paragraph branch carries exactly R1's difference: 10 cells x 6.
  check(paragraphBranch == 60, "the paragraph branch decided " +
                                   std::to_string(paragraphBranch) +
                                   " ops, expected 60");

  // R2: a recorded t1 op (Backspace at the start of the paragraph after a
  // table; Writer restores, nothing changes) with its after-read replaced by a
  // different paragraph's, the shape of a caret that moved while the document
  // did not.
  int r2 = 0;
  for (const Op &op : ops) {
    if (op.arm != "t1")
      continue;
    check(op.beforePos == 0, "t1 op before-read is not at the paragraph start");
    const cd::ParagraphRead moved = cd::paragraphReadOf("Cell text", 4, 0);
    const cd::Judgement guarded = cd::judgeAtReturn(
        op.key, op.undoBefore, true, op.undoAfter, beforeRead(op), moved);
    check(guarded.verdict == cd::Verdict::BoundaryNoop,
          "R2 " + cellOf(op) + ": the guarded decider judged a moved caret");
    check(saysDeleted(unguarded(op, moved)),
          "R2 " + cellOf(op) + ": the unguarded variant did not fail");
    ++r2;
  }
  check(r2 == 15, "R2 ran on " + std::to_string(r2) + " t1 ops, expected 15");

  // R3: accessibility unavailable.
  std::map<std::string, int> degradedWrong;
  for (const Op &op : ops) {
    check(cd::judgeBeforeKey(false, true, beforeRead(op)) != nullptr,
          "R3 " + cellOf(op) + ": the a11y guard let the key through");
    const cd::ParagraphRead absent;
    check(cd::judgeBeforeKey(true, true, absent) != nullptr,
          "R3 " + cellOf(op) + ": a failed before-read let the key through");
    // What going on without it would have answered.
    if (saysDeleted(unguarded(op, absent)) != op.deleted)
      ++degradedWrong[cellOf(op)];
  }
  for (const auto &[cell, n] : cellOps) {
    const bool grouped = cell.rfind("g1 ", 0) == 0 || cell.rfind("g2 ", 0) == 0;
    check(degradedWrong[cell] == (grouped ? 6 : 0),
          "R3 " + cell + ": the degraded decider mislabels " +
              std::to_string(degradedWrong[cell]));
  }

  // R4: the paragraph branch with a failed after-read.
  int r4 = 0;
  for (const Op &op : ops) {
    if (op.undoAfter != op.undoBefore ||
        !cd::caretStrictlyInside(op.key, beforeRead(op)))
      continue;
    const cd::Judgement j = cd::judgeAtReturn(op.key, op.undoBefore, true,
                                              op.undoAfter, beforeRead(op),
                                              cd::ParagraphRead{});
    check(j.verdict == cd::Verdict::Refused && j.keyPosted,
          "R4 " + cellOf(op) + ": a failed after-read was not refused with the key posted");
    ++r4;
  }
  check(r4 == 60, "R4 ran on " + std::to_string(r4) + " ops, expected 60");

  // Without its own failures this program would print nothing either way.
  std::printf("caret-delete witness: %zu ops, %zu cells, paragraph branch %d, "
              "R2 %d, R4 %d, failures %d\n",
              ops.size(), cellOps.size(), paragraphBranch, r2, r4, gFailures);
  return gFailures == 0 ? 0 : 1;
}
